    document.getElementById('endless-start').addEventListener('click', () => startGame('endless'));

    function loop(now) {
      const dt = Math.min(0.05, (now - state.lastTime) / 1000);
      state.lastTime = now;
      update(dt);
      render();
      requestAnimationFrame(loop);
    }

    buildHearts();
    updateLivesUI();
    updateControllerStatus(null);
    state.lastTime = performance.now();
